/* Randly language menu (generated by patch_lang_menu.py)
   Replaces the plain language <select> in page headers with a flag menu.
   - Languages and links come from the page's own <link rel="alternate" hreflang="..."> tags,
     so any new page that has those tags + these two files gets the menu automatically.
   - Items are real links (crawlable, work without extra JS).
   - On the chat home pages only the landing-page selector is replaced (the old <select> stays hidden in the
     page so the existing scripts keep working); the chat screen itself is untouched. */
(function () {
  'use strict';
  var HOME = !!document.getElementById('landingPage');

  var ORDER = ['ar', 'en', 'es', 'fr', 'de', 'it', 'pt', 'tr', 'ru', 'hi', 'id', 'zh'];
  var NAMES = { ar: 'العربية', en: 'English', es: 'Español', fr: 'Français', de: 'Deutsch', it: 'Italiano',
    pt: 'Português', tr: 'Türkçe', ru: 'Русский', hi: 'हिन्दी', id: 'Bahasa Indonesia', zh: '中文' };
  var S = '<svg width="30" height="30" viewBox="0 0 30 30" aria-hidden="true" focusable="false">';
  var FLAGS = {
    ar: S + '<rect width="15" height="15" fill="#006c35"/><rect x="3.5" y="4.5" width="8" height="1.6" rx="0.8" fill="#fff"/><rect x="3" y="9.6" width="9" height="1.1" rx="0.5" fill="#fff"/><g transform="translate(15 0)"><rect width="15" height="5" fill="#ce1126"/><rect y="5" width="15" height="5" fill="#fff"/><rect y="10" width="15" height="5" fill="#000"/><circle cx="7.5" cy="7.5" r="1.6" fill="#c09300"/></g><g transform="translate(0 15)"><rect width="15" height="5" fill="#00732f"/><rect y="5" width="15" height="5" fill="#fff"/><rect y="10" width="15" height="5" fill="#000"/><rect width="4.2" height="15" fill="#f00"/></g><g transform="translate(15 15)"><rect width="15" height="15" fill="#c1272d"/><path d="M7.5 3.3L9.97 10.9L3.51 6.2L11.49 6.2L5.03 10.9Z" fill="none" stroke="#006233" stroke-width="0.9" stroke-linejoin="round"/></g><path d="M15 0V30M0 15H30" stroke="rgba(255,255,255,0.9)" stroke-width="0.8"/></svg>',
    en: S + '<rect width="30" height="30" fill="#012169"/><path d="M0 0L30 30M30 0L0 30" stroke="#fff" stroke-width="6"/><path d="M0 0L30 30M30 0L0 30" stroke="#c8102e" stroke-width="2.4"/><path d="M15 0V30M0 15H30" stroke="#fff" stroke-width="10"/><path d="M15 0V30M0 15H30" stroke="#c8102e" stroke-width="6"/></svg>',
    es: S + '<rect width="30" height="30" fill="#aa151b"/><rect y="7.5" width="30" height="15" fill="#f1bf00"/></svg>',
    fr: S + '<rect width="10" height="30" fill="#0055a4"/><rect x="10" width="10" height="30" fill="#fff"/><rect x="20" width="10" height="30" fill="#ef4135"/></svg>',
    de: S + '<rect width="30" height="10" fill="#000"/><rect y="10" width="30" height="10" fill="#d00"/><rect y="20" width="30" height="10" fill="#ffce00"/></svg>',
    it: S + '<rect width="10" height="30" fill="#009246"/><rect x="10" width="10" height="30" fill="#fff"/><rect x="20" width="10" height="30" fill="#ce2b37"/></svg>',
    pt: S + '<rect width="30" height="30" fill="#da291c"/><rect width="12" height="30" fill="#046a38"/><circle cx="12" cy="15" r="4.2" fill="#ffe000"/><circle cx="12" cy="15" r="2.4" fill="#da291c"/></svg>',
    tr: S + '<rect width="30" height="30" fill="#e30a17"/><circle cx="13" cy="15" r="7" fill="#fff"/><circle cx="15" cy="15" r="5.6" fill="#e30a17"/><polygon points="20.5,11.8 21.3,13.9 23.5,14.0 21.7,15.4 22.4,17.6 20.5,16.3 18.6,17.6 19.3,15.4 17.5,14.0 19.7,13.9" fill="#fff"/></svg>',
    ru: S + '<rect width="30" height="10" fill="#fff"/><rect y="10" width="30" height="10" fill="#0039a6"/><rect y="20" width="30" height="10" fill="#d52b1e"/></svg>',
    hi: S + '<rect width="30" height="10" fill="#f93"/><rect y="10" width="30" height="10" fill="#fff"/><rect y="20" width="30" height="10" fill="#138808"/><circle cx="15" cy="15" r="3.2" fill="none" stroke="#000080" stroke-width="1"/></svg>',
    id: S + '<rect width="30" height="15" fill="#f00"/><rect y="15" width="30" height="15" fill="#fff"/></svg>',
    zh: S + '<rect width="30" height="30" fill="#de2910"/><polygon points="8.0,4.0 9.2,7.4 12.8,7.5 9.9,9.6 10.9,13.0 8.0,11.0 5.1,13.0 6.1,9.6 3.2,7.5 6.8,7.4" fill="#ffde00"/><polygon points="15.0,1.9 15.4,3.0 16.5,3.0 15.6,3.7 15.9,4.8 15.0,4.2 14.1,4.8 14.4,3.7 13.5,3.0 14.6,3.0" fill="#ffde00"/><polygon points="18.0,5.4 18.4,6.5 19.5,6.5 18.6,7.2 18.9,8.3 18.0,7.7 17.1,8.3 17.4,7.2 16.5,6.5 17.6,6.5" fill="#ffde00"/><polygon points="18.0,10.4 18.4,11.5 19.5,11.5 18.6,12.2 18.9,13.3 18.0,12.7 17.1,13.3 17.4,12.2 16.5,11.5 17.6,11.5" fill="#ffde00"/><polygon points="15.0,13.9 15.4,15.0 16.5,15.0 15.6,15.7 15.9,16.8 15.0,16.1 14.1,16.8 14.4,15.7 13.5,15.0 14.6,15.0" fill="#ffde00"/></svg>'
  };
  var CHEV = '<svg class="lm-chev" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>';
  var CHECK = '<svg class="lm-check" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12l5 5L20 7"/></svg>';

  function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;'); }

  function collect() {
    var map = {};
    var links = document.querySelectorAll('link[rel="alternate"][hreflang]');
    for (var i = 0; i < links.length; i++) {
      var code = (links[i].getAttribute('hreflang') || '').toLowerCase().split('-')[0];
      var href = links[i].getAttribute('href');
      if (!code || code === 'x' || !href || !NAMES[code]) continue;
      try { map[code] = new URL(href, location.href).pathname + (new URL(href, location.href).search || ''); }
      catch (e) { map[code] = href; }
    }
    return map;
  }

  function currentLang(map) {
    var l = (document.documentElement.getAttribute('lang') || '').toLowerCase().split('-')[0];
    if (NAMES[l]) return l;
    for (var k in map) { if (map[k] === location.pathname) return k; }
    return 'en';
  }

  function init() {
    if (document.querySelector('[data-lm]')) return;
    var stale = document.querySelectorAll('.lm-pop');
    for (var si = 0; si < stale.length; si++) if (stale[si].parentNode) stale[si].parentNode.removeChild(stale[si]);
    var map = collect();
    var codes = ORDER.filter(function (c) { return map[c]; });
    if (codes.length < 2) return;
    var cur = currentLang(map);
    if (!map[cur]) cur = codes[0];

    var select = HOME ? document.getElementById('landingLangSelect') : document.querySelector('.app-header select.site-lang-select');
    var host = select ? select.parentNode : (HOME ? null : (document.querySelector('.app-header .header-right') || document.querySelector('.app-header')));
    if (!host) return;

    var id = 'lmPop' + Math.floor(Math.random() * 1e6);
    var wrap = document.createElement('div');
    wrap.className = 'lm';
    wrap.setAttribute('data-lm', '');
    wrap.innerHTML = '<button type="button" class="lm-btn" aria-haspopup="true" aria-expanded="false" aria-controls="' + id + '" aria-label="Language: ' + esc(NAMES[cur]) + '">' +
      '<span class="lm-flag">' + FLAGS[cur] + '</span><span>' + cur.toUpperCase() + '</span>' + CHEV + '</button>';
    var btn = wrap.firstChild;

    var pop = document.createElement('nav');
    pop.className = 'lm-pop';
    pop.id = id;
    pop.hidden = true;
    pop.setAttribute('aria-label', 'Language');
    pop.innerHTML = codes.map(function (c) {
      return '<a class="lm-item" href="' + esc(map[c]) + '" hreflang="' + c + '" lang="' + c + '"' + (c === cur ? ' aria-current="true"' : '') + '>' +
        '<span class="lm-flag">' + FLAGS[c] + '</span><span class="lm-name">' + esc(NAMES[c]) + '</span>' + (c === cur ? CHECK : '') + '</a>';
    }).join('');

    if (select && HOME) {
      host.insertBefore(wrap, select);
      select.hidden = true; select.style.display = 'none'; select.setAttribute('aria-hidden', 'true'); select.tabIndex = -1;
    } else if (select) host.replaceChild(wrap, select);
    else host.appendChild(wrap);
    document.body.appendChild(pop);

    function place() {
      var r = btn.getBoundingClientRect();
      var w = Math.min(280, window.innerWidth - 16);
      var left = (r.left + r.width / 2 > window.innerWidth / 2) ? r.right - w : r.left;
      left = Math.max(8, Math.min(left, window.innerWidth - w - 8));
      pop.style.left = left + 'px';
      pop.style.top = (r.bottom + 8) + 'px';
      pop.style.width = w + 'px';
    }
    function open() {
      pop.hidden = false; btn.setAttribute('aria-expanded', 'true'); place();
    }
    function close(focusBtn) {
      pop.hidden = true; btn.setAttribute('aria-expanded', 'false');
      if (focusBtn) btn.focus();
    }
    btn.addEventListener('click', function (e) { e.stopPropagation(); pop.hidden ? open() : close(false); });
    document.addEventListener('click', function (e) { if (!pop.hidden && !pop.contains(e.target) && !wrap.contains(e.target)) close(false); });
    window.addEventListener('resize', function () { if (!pop.hidden) place(); });
    window.addEventListener('scroll', function () { if (!pop.hidden) place(); }, { passive: true });
    pop.addEventListener('click', function (e) {
      var a = e.target.closest ? e.target.closest('a.lm-item') : null;
      if (a) { try { localStorage.setItem('randly_lang', a.getAttribute('hreflang')); } catch (err) {} }
    });
    document.addEventListener('keydown', function (e) {
      if (pop.hidden) return;
      var items = Array.prototype.slice.call(pop.querySelectorAll('a.lm-item'));
      var i = items.indexOf(document.activeElement);
      if (e.key === 'Escape') { e.preventDefault(); close(true); }
      else if (e.key === 'ArrowDown') { e.preventDefault(); items[(i + 1 + items.length) % items.length].focus(); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); items[(i <= 0 ? items.length : i) - 1].focus(); }
      else if (e.key === 'Home') { e.preventDefault(); items[0].focus(); }
      else if (e.key === 'End') { e.preventDefault(); items[items.length - 1].focus(); }
    });
  }

  if (HOME) {
    // The home pages' own scripts rebuild the header after load and can wipe the menu,
    // so (re)build it when needed and keep the old <select> hidden.
    var timer = null;
    var tick = function () {
      timer = null;
      var s = document.getElementById('landingLangSelect');
      if (!s) return;
      if (document.querySelector('[data-lm]')) { s.hidden = true; s.style.display = 'none'; }
      else init();
    };
    var soon = function () { if (!timer) timer = setTimeout(tick, 30); };
    var go = function () { setTimeout(tick, 0); setTimeout(tick, 500); setTimeout(tick, 1500); };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', go); else go();
    window.addEventListener('load', go);
    if (window.MutationObserver) {
      var mo = new MutationObserver(soon);
      var start = function () { mo.observe(document.body, { childList: true, subtree: true }); setTimeout(function () { mo.disconnect(); }, 15000); };
      if (document.body) start(); else document.addEventListener('DOMContentLoaded', start);
    }
  } else if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();
